package com.travelbird.savedroute.repository;
import com.travelbird.savedroute.entity.SavedRoute;import org.springframework.data.jpa.repository.*;import org.springframework.data.repository.query.Param;
public interface AiPreviewSavedRouteRepository extends JpaRepository<SavedRoute,Long>{@Modifying @Query(value="INSERT INTO saved_routes (user_id,source_type,source_id,source_available,saved_at,updated_at) VALUES (:userId,'AI_PREVIEW',:previewId,TRUE,CURRENT_TIMESTAMP,CURRENT_TIMESTAMP) ON DUPLICATE KEY UPDATE source_available=TRUE,updated_at=CURRENT_TIMESTAMP",nativeQuery=true)int savePreview(@Param("userId")Long userId,@Param("previewId")Long previewId);@Modifying @Query(value="DELETE FROM saved_routes WHERE user_id=:userId AND source_type='AI_PREVIEW' AND source_id=:previewId",nativeQuery=true)int deletePreview(@Param("userId")Long userId,@Param("previewId")Long previewId);@Query(value="SELECT COUNT(*) FROM saved_routes WHERE source_type='AI_PREVIEW' AND source_id=:previewId AND source_available=TRUE",nativeQuery=true)long countPreview(@Param("previewId")Long previewId);}
